"use strict";(self.webpackChunkuxcam=self.webpackChunkuxcam||[]).push([[6401],{75501:function(e,t,a){a.r(t),a.d(t,{Head:function(){return l},default:function(){return c}});var s=a(96540),n=a(86997),o=a(54727);var i={seo:{title:"Case study | Costa Coffee",description:"How Costa Coffee identified an opportunity to increase their app user registrations by 15% with UXCam.",image:"https://images.ctfassets.net/vv1yxl437u7d/3Mn0AbpUmb4aFxUXNgpzY6/77b23638bee2a4c3cc29e6336ace2e1f/metaimageNEW.png"},hero:{industry:"Hospitality",title:"How Costa Coffee Increased Its <span>Registrations by 15% With UXCam</span>",description:"Costa Coffee is a British multinational coffee brand. It is the second largest coffee shop chain in the world and the largest in the UK. Its acquisition by Coca-Cola in 2019 propelled Costa into a truly global brand with locations in 41 countries.",featuresUsed:[{label:"Session Recording",url:"/experience-analytics/session-replay"},{label:"Funnel Analytics",url:"/product-analytics/funnels"},{label:"Event Analytics",url:"/product-analytics/event-analytics"}],image:"https://images.ctfassets.net/vv1yxl437u7d/6RB4RlORWJhszqX1HzE872/e0e010a88900364fc566211d90a9e51b/Frame.svg",vimeoId:"844179557?h=1b215f68ca"},stats:[{value:"> 1M Installs",label:"on Google Play Store"},{value:"30% Drop-offs",label:"during app registration flow"},{value:"15% Drop-offs",label:"attributed to invalid password entries"}],challenge:{title:"The Challenge",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/1Ov4GcUZwhwz6Gdk7x9TIS/ad9823ae58f2e2026f64d865f820a987/Vector.svg",paragraphs:["Costa Coffee’s loyalty program is a revenue engine. Customers who register through the app spend 173% more per year than non-registered users. But the funnel had a leak.","Over a six-month analysis period, the team discovered that 30% of new app users dropped off between downloading the app and completing loyalty registration. That translated to thousands of lost customers every single week, each one worth 2.7x in annual revenue compared to an unregistered user.","Even though the team had already reached that conclusion by using a traditional analytics tool, the numbers alone did not explain the underlying user behavior that led to user drop-offs. This made Costa seek a complete analytics solution that would provide answers into why this was happening."],quote:{text:"Because of UXCam, we can get really granular and understand the exact reasons behind why users are dropping off during the sign-up process.",author:"Daniel Tomlinson",role:"Global Digital Analytics Manager",image:"https://images.ctfassets.net/vv1yxl437u7d/59YasLV43hIP1ASDHuqJrc/6688ea445d1ec899d215c762abd866d3/costathumb.png"}},solution:{title:"The Solution",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/28xui9UzDyaFzt7EfaJuio/74b1070ae5cc420b5ac71c1dee040858/Vector.svg",paragraphs:["Daniel, Costa’s Global Digital Analytics Manager, found UXCam to be the comprehensive platform that would let the team move on from vanity metrics. He quickly started to identify the main issues so that the team could take steps to resolve them.","With UXCam, he tracked custom events for all of the critical registration metrics. When he added funnels, Daniel was able to paint a complete picture of the way users sign up for the Costa Coffee app.","This combination of custom events and funnels led to the single biggest bottleneck: About 15% of new users dropped off after entering invalid passwords.","Daniel then set up more events for each type of invalid password reason and researched the session recordings associated with these events. Having found some interesting patterns, the Analytics team proposed design changes that would revamp the affected section of the app."],quote:{text:"If something goes wrong within the app, UXCam is the first port of call to understand what’s going on. Playing a key role across multiple teams, UXCam is now an integral part of the launch and live ops strategy.",author:"Daniel Tomlinson",role:"Global Digital Analytics Manager",image:"https://images.ctfassets.net/vv1yxl437u7d/59YasLV43hIP1ASDHuqJrc/6688ea445d1ec899d215c762abd866d3/costathumb.png"}},whatsNext:{title:"What’s next?",backgroundImage:"https://images.ctfassets.net/vv1yxl437u7d/Bc9n79vDsJLoV0HUy6g4j/db1b14e3e0162ced77ac4f4e7f6b5e6a/Path-7.svg",paragraphs:["The Analytics team narrowed down the single biggest reason behind user drop-offs. With this in mind, Costa Coffee is currently overhauling its registration process while continuously looking for new analytics insights.","Costa Coffee has a big year ahead with some major app features going live. UXCam is playing a key role across multiple teams and is now an integral part of the company’s launch and live ops strategy."],quote:{text:"I understand the value that UXCam brings across the board, and now I am getting other teams at Costa Coffee to try it out along with us.",author:"Daniel Tomlinson",role:"Global Digital Analytics Manager",image:"https://images.ctfassets.net/vv1yxl437u7d/59YasLV43hIP1ASDHuqJrc/6688ea445d1ec899d215c762abd866d3/costathumb.png"}}},r=a(17437);const l=()=>(0,r.Y)(s.Fragment,null,(0,r.Y)(o.A,{title:i.seo.title,description:i.seo.description,image:{file:{url:i.seo.image}}}),(0,r.Y)("link",{rel:"canonical",href:"https://uxcam.com/case-study/costa-coffee/"}),(0,r.Y)("link",{rel:"alternate",hrefLang:"en",href:"https://uxcam.com/case-study/costa-coffee/"}),(0,r.Y)("link",{rel:"alternate",hrefLang:"es",href:"https://uxcam.com/es/case-study/costa-coffee/"}),(0,r.Y)("link",{rel:"alternate",hrefLang:"pt-BR",href:"https://uxcam.com/br/case-study/costa-coffee/"}),(0,r.Y)("link",{rel:"alternate",hrefLang:"x-default",href:"https://uxcam.com/case-study/costa-coffee/"}));var c=()=>(0,r.Y)(n.A,{data:i})}}]);